commit 60381148345a422d58981c43d3202bb753b48ac6
Author:     Geoff Lankow <geoff@darktrojan.net>
AuthorDate: Thu Oct 16 15:36:52 2025 -0700
Commit:     Geoff Lankow <geoff@darktrojan.net>
CommitDate: Thu Oct 16 15:36:52 2025 -0700

    Bug 1994411 - Keep taskbar progress objects alive in memory until the window closes. r=tobyp

    If we let the object be garbage-collected, the taskbar icon disappears on Windows.

    Differential Revision: https://phabricator.services.mozilla.com/D268812

diff --git a/mail/components/compose/content/MsgComposeCommands.js b/mail/components/compose/content/MsgComposeCommands.js
index 4a3616033ae..01942300631 100644
--- a/mail/components/compose/content/MsgComposeCommands.js
+++ b/mail/components/compose/content/MsgComposeCommands.js
@@ -100,7 +100,16 @@ const lazy = {};

 ChromeUtils.defineESModuleGetters(lazy, {
   MailStringUtils: "resource:///modules/MailStringUtils.sys.mjs",
-  TaskbarProgress: "resource:///modules/TaskbarProgress.sys.mjs",
+});
+
+ChromeUtils.defineLazyGetter(lazy, "taskbarProgress", () => {
+  // Once we have this object, we must hold a reference to it until the window
+  // closes. Otherwise it could be cleaned up by garbage collection, which
+  // causes the window to disappear from the taskbar on Windows.
+  const { TaskbarProgress } = ChromeUtils.importESModule(
+    "resource:///modules/TaskbarProgress.sys.mjs"
+  );
+  return TaskbarProgress.getTaskbarProgress(window);
 });

 /**
@@ -912,9 +921,10 @@ var progressListener = {
       progressMeter.value = 0;
       document.getElementById("statusText").textContent = "";
       // Clear taskbar/dock progress.
-      lazy.TaskbarProgress.showProgress(
-        window,
-        Ci.nsITaskbarProgress.STATE_NO_PROGRESS
+      lazy.taskbarProgress?.setProgressState(
+        Ci.nsITaskbarProgress.STATE_NO_PROGRESS,
+        0,
+        0
       );
       Services.obs.notifyObservers(
         { composeWindow: window },
@@ -945,8 +955,7 @@ var progressListener = {
       // Taskbar/dock progress. Don't show progress for messages smaller than
       // the send chunk size.
       if (aMaxTotalProgress > 65536) {
-        lazy.TaskbarProgress.showProgress(
-          window,
+        lazy.taskbarProgress?.setProgressState(
           Ci.nsITaskbarProgress.STATE_NORMAL,
           aCurTotalProgress,
           aMaxTotalProgress
@@ -957,9 +966,10 @@ var progressListener = {
       document.getElementById("compose-progressmeter").removeAttribute("value");

       // Just clear taskbar/dock progress.
-      lazy.TaskbarProgress.showProgress(
-        window,
-        Ci.nsITaskbarProgress.STATE_NO_PROGRESS
+      lazy.taskbarProgress?.setProgressState(
+        Ci.nsITaskbarProgress.STATE_NO_PROGRESS,
+        0,
+        0
       );
     }
   },
diff --git a/mail/modules/TaskbarProgress.sys.mjs b/mail/modules/TaskbarProgress.sys.mjs
index d55cc820523..118fd110a51 100644
--- a/mail/modules/TaskbarProgress.sys.mjs
+++ b/mail/modules/TaskbarProgress.sys.mjs
@@ -7,8 +7,12 @@
  *
  * @param {mozIDOMWindowProxy} window - The window to associate with this
  *   progress display.
+ * @returns {?nsITaskbarProgress}
  */
 function getTaskbarProgress(window) {
+  if (!window.docShell) {
+    return null;
+  }
   if ("@mozilla.org/windows-taskbar;1" in Cc) {
     const winTaskbar = Cc["@mozilla.org/windows-taskbar;1"].getService(
       Ci.nsIWinTaskbar
@@ -34,20 +38,5 @@ function getTaskbarProgress(window) {
 }

 export const TaskbarProgress = {
-  /**
-   * Display the progress on the OS taskbar icon of `window`.
-   * See nsITaskbarProgress.idl for more info.
-   *
-   * @param {mozIDOMWindowProxy} window - The window to associate with this
-   *   progress display.
-   * @param {nsTaskbarProgressState} state
-   * @param {number} currentValue
-   * @param {number} maxValue
-   */
-  showProgress(window, state, currentValue = 0, maxValue = 0) {
-    if (!window.docShell) {
-      return;
-    }
-    getTaskbarProgress(window)?.setProgressState(state, currentValue, maxValue);
-  },
+  getTaskbarProgress,
 };
